if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const animate=(els)=>{if(window.gsap){window.gsap.fromTo(els,{y:7,opacity:.55},{y:0,opacity:1,duration:.65,stagger:.045,ease:'power2.out',clearProps:'transform,opacity'})}else if(Element.prototype.animate){els.forEach((el,i)=>el.animate([{transform:'translateY(5px)',opacity:.65},{transform:'translateY(0)',opacity:1}],{duration:460,delay:i*35,easing:'ease-out'}))}};const hero=$$('.hero h1,.hero .role,.page-head h1,.article h1');animate(hero);if('IntersectionObserver'in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){animate([e.target]);io.unobserve(e.target)}}),{threshold:.14});$$('.section-heading,.project,.entry').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight)io.observe(el)})}}
